package com.dating.backend.matching;
import com.dating.backend.entity.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
class AccountSafetyTest extends SocialServiceTest {
 @Autowired AccountService accounts; @Autowired ProfileModeration moderation;
 @Autowired com.dating.backend.config.JwtUtil jwt;
 @Test void unblockDoesNotUndoOtherMembersBlock(){social.direct(a.getEmail(),request());social.block(a.getEmail(),b.getId());social.block(b.getEmail(),a.getId());assertEquals(1,social.blocks(a.getEmail()).size());social.unblock(a.getEmail(),b.getId());assertTrue(social.blocks(a.getEmail()).isEmpty());assertFalse(social.available(a.getId(),b.getId()));social.unblock(b.getEmail(),a.getId());assertTrue(social.available(a.getId(),b.getId()));}
 @Test void unmatchEndsBothSidesAndCannotReopenForCredits(){social.like(a.getEmail(),b.getId());var r=social.like(b.getEmail(),a.getId());assertTrue(social.messages(a.getEmail(),r.roomId(),0,0).matched());social.unmatch(a.getEmail(),b.getId());assertTrue(social.rooms(a.getEmail()).isEmpty());assertTrue(social.rooms(b.getEmail()).isEmpty());assertTrue(social.overview(b.getEmail()).matched().isEmpty());assertThrows(ResponseStatusException.class,()->social.direct(a.getEmail(),request()));assertThrows(ResponseStatusException.class,()->social.like(b.getEmail(),a.getId()));}
 @Test void restingPausesCardsButKeepsChat(){var room=social.direct(a.getEmail(),request()).roomId();accounts.rest(a.getEmail(),true);assertTrue(daily.today(a.getEmail()).cards().stream().allMatch(x->x.state().equals("PAUSED")));social.send(a.getEmail(),room,new SocialService.SendRequest("still here",java.util.UUID.randomUUID().toString()));assertEquals(2,social.messages(b.getEmail(),room,0,0).messages().size());accounts.rest(a.getEmail(),false);assertEquals("OPEN",daily.today(a.getEmail()).cards().get(0).state());}
 @Test void profileStaysApprovedUntilCurrentRevisionIsApproved(){moderation.beforeEdit(b);b.setNickname("changed");assertEquals("b",social.profile(a.getEmail(),b.getId()).person().nickname());long revision=b.getProfileRevision();moderation.beforeEdit(b);assertThrows(ResponseStatusException.class,()->moderation.decide(b.getId(),revision,true,"ok"));moderation.decide(b.getId(),b.getProfileRevision(),false,"보완");assertEquals("b",social.profile(a.getEmail(),b.getId()).person().nickname());moderation.beforeEdit(b);moderation.decide(b.getId(),b.getProfileRevision(),true,"승인");assertEquals("changed",social.profile(a.getEmail(),b.getId()).person().nickname());}
 @Test void logoutAllRevokesAccessAndWithdrawalHidesProfile(){String token=jwt.createToken(a.getEmail());assertTrue(jwt.validateToken(token));accounts.logoutAll(a.getEmail());assertFalse(jwt.validateToken(token));String next=jwt.createToken(a.getEmail());assertTrue(jwt.validateToken(next));accounts.withdraw(a.getEmail(),new AccountService.Withdrawal(null,"회원탈퇴"));assertFalse(jwt.validateToken(next));assertFalse(social.available(b.getId(),a.getId()));}
 @Test void preferenceHoursHandleMidnightAndKeepInbox(){known(b,a);var p=accounts.preferences(a.getEmail(),new AccountService.Preferences(false,true,true,true,true,true,22,8)).notifications();assertFalse(AccountService.allowed(p,"LIKE:1"));assertTrue(AccountService.allowed(p,"CHAT:1"));assertTrue(AccountService.quiet(p,23));assertTrue(AccountService.quiet(p,7));assertFalse(AccountService.quiet(p,8));assertFalse(AccountService.quiet(p,21));social.like(b.getEmail(),a.getId());assertEquals(1,inbox.list(a.getEmail(),0).size());}
}
